export const DELEGATION_GUIDANCE = 'Handle small or tightly coupled tasks directly. Delegate when parallel work, specialized roles, or context isolation offers a clear benefit. Avoid duplicating substantial context; reuse a suitable existing agent. Send progress messages when a blocker or important change needs coordination. A successful message confirms inbox acceptance, not processing or a reply.';
export const WAKE_GUIDANCE = 'Automatic agent messages share a limit across your collaboration tree until user input resets it. A limit error rejects only that send; do not repeatedly retry it. Native completion notifications are automatic and do not use this allowance. Use task_result: true only for a completed-task report to your direct parent, not ordinary requests or progress updates.';
